import{z as i,x as A,o as e,c as l,q as r,j as o,D as t,d as s,s as h,S as n}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Stambaugh 偏差","description":"","frontmatter":{"title":"Stambaugh 偏差","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/stambaugh-bias.md","filePath":"quant/stambaugh-bias.md","lastUpdated":1791063341000}'),B={name:"quant/stambaugh-bias.md"};function m(u,a,p,_,b,d){const E=A("Mermaid");return e(),l("div",null,[a[2]||(a[2]=r('<h1 id="stambaugh-偏差" tabindex="-1">Stambaugh 偏差 <a class="header-anchor" href="#stambaugh-偏差" aria-label="Permalink to &quot;Stambaugh 偏差&quot;">​</a></h1><div class="epigraph"><p>用持续而带新息的预测变量去预报收益时，回归元的新息与收益相关，最小二乘的斜率在有限样本里系统性地偏向远离零的一侧。</p><footer>—— Stambaugh, Predictive Regressions, Journal of Financial Economics, 1999</footer></div><p><a href="/quant/event-study">事件研究</a> 的识别靠短窗；预测回归的识别靠「今天的估值预报明天的收益」。股利价格比、短期利率、通胀一类变量高度持续，几乎像单位根，新息又与同期收益相关——价格涨则 \\(D/P\\) 立刻变小。Stambaugh 给出这种设定下 OLS 的有限样本偏误：即使真 \\(\\beta=0\\)，估计也会像有预测力。本课缺口是 <strong>HAC 与聚类都不消这条偏</strong>，因为它来自回归元的设定而非残差方差公式。后课把预测期拉长、观测重叠，偏误会与重叠推断缠在一起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2> \\[r_{t+1}=\\alpha+\\beta x_t+u_{t+1},\\qquad x_{t+1}=\\rho x_t+v_{t+1}, \\]<p>\\(\\rho\\) 接近 1，\\(E[u_{t+1}v_{t+1}]=\\sigma_{uv}\\lt 0\\)（对 \\(D/P\\)：收益正冲击伴随 \\(x\\) 负冲击）。Stambaugh 证明</p> \\[E[\\hat\\beta-\\beta]\\approx\\frac{\\sigma_{uv}}{\\sigma_v^2}E[\\hat\\rho-\\rho]. \\]<p>\\(\\hat\\rho\\) 在近单位根下偏下（\\(\\hat\\rho\\lt \\rho\\)），\\(\\sigma_{uv}\\lt 0\\) 则 \\(E[\\hat\\beta-\\beta]\\gt 0\\)：OLS 倾向于找出「\\(x\\) 能正向预测收益」。问题是：样本内 \\(t\\) 显著，究竟是可预报性，还是这条偏误。</p><p>Nelson 与 Kim（1993）用模拟展示了同类现象；Stambaugh 给出解析近似。对象是<strong>有限样本</strong>，不是渐近不一致——\\(T\\to\\infty\\) 时 OLS 仍一致，但金融的 \\(T\\) 以十年计，\\(\\rho=0.98\\) 的月度变量偏误可以吃掉真 \\(\\beta\\)。</p><p><span class="marginnote">直觉类比：\\(\\rho\\) 接近 1 时，\\(x\\) 几乎是随机游走，但有限样本里它「看起来」总在往均值回摆。OLS 误以为自己摸清了 \\(x\\) 的脾气，把收益里本来属于运气的部分记到了「\\(x\\) 回摆」的账上——斜率因此被系统性地夸大，而且方向恰好是「\\(x\\) 有预测力」的那一侧。</span></p><h3 id="与单位根、hac-的边界" tabindex="-1">与单位根、HAC 的边界 <a class="header-anchor" href="#与单位根、hac-的边界" aria-label="Permalink to &quot;与单位根、HAC 的边界&quot;">​</a></h3><p>\\(x\\) 若真是单位根且与 \\(u\\) 相关，进入局部到单位根的渐近，\\(t\\) 的极限不是正态。Newey–West 加大滞后不会把 \\(E[\\hat\\rho-\\rho]\\) 变成零。预白化、把 \\(x\\) 差分，会改变问题：差分后的 \\(x\\) 往往没有预测力，对象变成「变化」而不是「水平估值」。</p><p><span class="marginnote">常见误区：「我用了 Newey–West 稳健标准误，所以结论稳」。NW 修正的是标准误（区间有多宽），Stambaugh 偏差是斜率本身的中心偏了（针扎在错误的位置）。区间再「稳健」，覆盖的也是错的心脏——这正是本课反复强调 HAC 不消这条偏的原因。</span></p><p><span class="marginnote">样本内 \\(R^2\\) 高、样本外崩溃，是这条偏的常见经验貌。Goyal–Welch 对股权溢价预测的样本外检验，应与 Stambaugh 偏一起读：不是「市场不可预测」的哲学，而是水平持续回归元的统计陷阱。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>偏误修正。</strong> 用 \\(\\hat\\rho\\) 的已知偏公式去减 \\(E[\\hat\\beta-\\beta]\\)（Stambaugh 的解析修正）；Amihud–Hurvich 一类改进；或直接模拟：在 \\(\\beta=0\\) 下按估计的 \\((\\rho,\\sigma_{uv})\\) 抽 \\((r,x)\\)，看 \\(\\hat\\beta\\) 的分布，用该分布当零。</p><p><strong>推断。</strong> 局部到单位根的临界值、Campbell–Yogo 的 Bonferroni 区间、或 <a href="/quant/bootstrap-finance">bootstrap</a> 时必须保持 \\((u,v)\\) 的同期相关并整条重抽 \\(x\\) 路径——对行 i.i.d. 自助会拆掉持续性，低估偏误。</p><p><strong>多预测变量。</strong> 若干个近单位根 \\(x\\) 一起回归，偏误会在系数间分配，单变量修正不够。应报告联合样本外，而不是只修其中一个斜率。</p><h3 id="哪些回归元中招" tabindex="-1">哪些回归元中招 <a class="header-anchor" href="#哪些回归元中招" aria-label="Permalink to &quot;哪些回归元中招&quot;">​</a></h3><p>估值比率、利率、期限利差、通胀、消费财富比：持续且与价格同新息。过去 12 个月收益（动量）持续性弱得多，Stambaugh 项小，偏误不是主故事。已实现波动作预测元时，\\(\\rho\\) 高但 \\(\\sigma_{uv}\\) 的符号取决于杠杆，须单独估，不能套 \\(D/P\\) 的负号。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(\\hat\\rho\\) 偏下是近单位根 OLS 的经典结果（均值附近的序列被估得太均值回复）。\\(\\sigma_{uv}\\neq 0\\) 把这条偏传到 \\(\\hat\\beta\\)：估 \\(x\\) 的人用同一段价格新息，收益方程与 \\(x\\) 方程共享冲击。机制是<strong>共享新息 + 持续</strong>，不是异方差。所以 White 三明治可以给出「精确但有偏」的区间——覆盖的是错误中心。</p>',22)),(e(),o(n,null,{default:t(()=>[h(E,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20Start%5B%22%E6%98%AF%E5%90%A6%E7%94%A8%E6%B0%B4%E5%B9%B3%E5%80%BC%20x_t%20%E9%A2%84%E6%B5%8B%20r_%7Bt%2B1%7D%3F%22%5D%20--%3E%7C%22%E5%90%A6%22%7C%20Safe%5B%22%E5%81%8F%E8%AF%AF%E4%B8%8D%E9%80%82%E7%94%A8%22%5D%0A%20%20Start%20--%3E%7C%22%E6%98%AF%22%7C%20Q1%7B%22x%CC%82%20%E7%9A%84%20%CF%81%20%E6%8E%A5%E8%BF%91%201%20%E5%90%97%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%2C%20%E6%8C%81%E7%BB%AD%E6%80%A7%E5%BC%B1%22%7C%20Low%5B%22Stambaugh%20%E9%A1%B9%E5%B0%8F%2C%20%E5%B8%B8%E8%A7%84%E6%8E%A8%E6%96%AD%E5%A4%9F%E7%94%A8%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20Q2%7B%22x%20%E7%9A%84%E6%96%B0%E6%81%AF%E4%B8%8E%E6%94%B6%E7%9B%8A%E6%96%B0%E6%81%AF%E7%9B%B8%E5%85%B3%E5%90%97%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E5%87%A0%E4%B9%8E%E4%B8%8D%E7%9B%B8%E5%85%B3%22%7C%20Small%5B%22%E5%81%8F%E8%AF%AF%E5%8F%AF%E5%BF%BD%E7%95%A5%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%98%BE%E8%91%97%E7%9B%B8%E5%85%B3%22%7C%20Hit%5B%22%E4%B8%AD%E6%8B%9B%3A%20%E7%94%A8%E8%A7%A3%E6%9E%90%E4%BF%AE%E6%AD%A3%E6%88%96%E6%A8%A1%E6%8B%9F%E9%9B%B6%E5%88%86%E5%B8%83%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">这张图回答一个实务问题：手头的回归要不要做 Stambaugh 修正。两个闸门是持续性和新息相关——只有「水平值 + 高持续 + 新息相关」三项齐备才中招；动量、已实现波动这类低持续或新息正交的回归元不必套同一副药。</span></p><p>与 <a href="/quant/fama-macbeth">Fama–MacBeth</a> 的生成回归量不同：那里 \\(\\beta\\) 是估出来的载荷；这里 \\(x_t\\) 是观测到的，但<strong>动态上</strong>像生成的。Shanken 修的是第一步估计误差；Stambaugh 修的是预测元自回归的有限样本。</p><p><span class="marginnote">若能把 \\(x_t\\) 换成事先可知、且新息与 \\(u_{t+1}\\) 正交的变量（宏观意外的滞后），Stambaugh 项消失。许多「聪明」的同期宏观不是预先可知，会变成另一层前视。</span></p><h3 id="经济幅度" tabindex="-1">经济幅度 <a class="header-anchor" href="#经济幅度" aria-label="Permalink to &quot;经济幅度&quot;">​</a></h3><p>即使修正后 \\(\\beta\\gt 0\\)，可预报性的 \\(R^2\\) 仍常在几个百分点。偏误修正回答的是「零假设还能否拒绝」，不自动给出可交易夏普。交易成本与时变 \\(\\beta\\) 会把剩下的 \\(R^2\\) 再削一层。</p><p><span class="marginnote">数字实例：月度 \\(\\rho=0.98\\)、样本 20 年（\\(T=240\\)），\\(\\hat\\rho\\) 的偏约 \\(-(1+3\\rho)/T\\approx-0.016\\)；若 \\(\\sigma_{uv}/\\sigma_v^2=-10\\)，代入偏误公式得 \\(\\hat\\beta\\) 平均被推高约 \\(+0.16\\)。而真实的可预报性斜率往往只有百分之几——也就是说，偏误本身就能「无中生有」出一条显著的预测律。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(T\\) 短、\\(\\rho\\) 极近 1 时解析近似也差，应模拟。结构突变（\\(\\rho\\) 在样本中改变）让单 \\(\\rho\\) 修正错误。把 \\(x\\) 换成递归的样本外均值差，是 Welch–Goyal 的纪律，不是偏误公式的替代，但能挡住样本内过拟合。</p><p>工程：凡用估值水平预测收益，并列 OLS、\\(t\\)、Stambaugh 修正或模拟 p 值、样本外。不要只用 Newey–West 宣称稳健。不要在 \\(\\rho\\) 接近 1 时把 \\(x\\) 当普通平稳回归元做 <a href="/quant/var-irf">VAR</a> 脉冲还用标准 \\(t\\)。下一课把 \\(r_{t+1}\\) 换成 \\(r_{t+1}+\\cdots+r_{t+h}\\)，重叠会让 \\(t\\) 再膨胀一截。</p>',9)),(e(),o(n,null,{default:t(()=>[h(E,{id:"mermaid-88",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8C%81%E7%BB%AD%E9%A2%84%E6%B5%8B%E5%85%83%20x_t%22%5D%20--%3E%20R%5B%22%E6%94%B6%E7%9B%8A%E5%9B%9E%E5%BD%92%20r_%7Bt%2B1%7D%20%E5%AF%B9%20x_t%22%5D%0A%20%20X%20--%3E%20AR%5B%22x%20%E7%9A%84%20AR%3A%20%CF%81%CC%82%20%E5%81%8F%E4%B8%8B%22%5D%0A%20%20U%5B%22%E6%94%B6%E7%9B%8A%E6%96%B0%E6%81%AF%20u%22%5D%20--%3E%20CV%5B%22Cov(u%2Cv)%E2%89%A00%22%5D%0A%20%20V%5B%22x%20%E7%9A%84%E6%96%B0%E6%81%AF%20v%22%5D%20--%3E%20CV%0A%20%20AR%20--%3E%20BIAS%5B%22%CE%B2%CC%82%20%E6%9C%89%E9%99%90%E6%A0%B7%E6%9C%AC%E5%81%8F%22%5D%0A%20%20CV%20--%3E%20BIAS%0A%20%20BIAS%20--%3E%20FIX%5B%22%E8%A7%A3%E6%9E%90%E4%BF%AE%E6%AD%A3%20%2F%20%E6%A8%A1%E6%8B%9F%E9%9B%B6%E5%88%86%E5%B8%83%22%5D%0A%20%20HAC%5B%22HAC%20%E5%8F%AA%E6%94%B9%E5%88%86%E6%AF%8D%22%5D%20-.-%3E%7C%22%E4%B8%8D%E6%B6%88%E5%81%8F%22%7C%20BIAS%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持续预测元与收益共享新息时，OLS 的 \\(\\hat\\beta\\) 在有限样本偏向「有预测力」。</li><li>偏误公式连着 \\(E[\\hat\\rho-\\rho]\\) 与 \\(\\sigma_{uv}\\)；HAC、聚类、White 都不消除它。</li><li>推断应用偏误修正、局部到单位根区间，或保持相关结构的路径自助。</li><li>样本外检验是对抗这条偏与过拟合的纪律，不是附属图表。</li><li>出处：Stambaugh, <em>Journal of Financial Economics</em>, 1999；相关模拟见 Nelson and Kim, <em>Journal of Finance</em>, 1993。</li></ul>',2))])}const C=i(B,[["render",m]]);export{c as __pageData,C as default};
